const items = $input.all();
const trusted = ['lu.ma', 'luma.com', 'unstop.com', 'devfolio.co', 'tinkerhub.org', 'tinkerspace', 'meetup.com', 'konfhub.com', 'eventbrite.', 'hasgeek.com', 'fossunited.org'];
const cities = ['kochi', 'cochin', 'ernakulam', 'kalamassery', 'thrissur', 'kottayam', 'kozhikode', 'calicut', 'kerala'];
const eventWords = ['hackathon', 'workshop', 'bootcamp', 'meetup', 'conference', 'summit', 'competition', 'hack night', 'build night', 'demo day', 'devfest', 'webinar', 'training', 'sprint', 'ctf'];
const junk = /\/(tag|tags|category|categories|author|authors|search|page|feed)(\/|$)/i;
const seen = new Set();
const candidates = [];

for (const item of items) {
  const results = item.json.results || [];
  for (const result of results) {
    const url = String(result.url || '').trim();
    if (!url || seen.has(url) || !/^https?:\/\//i.test(url)) continue;
    if (/\.(pdf|zip|docx?|xlsx?|pptx?)$/i.test(url)) continue;
    if (junk.test(url)) continue;
    seen.add(url);
    const title = String(result.title || '').slice(0, 300);
    const snippet = String(result.content || '').slice(0, 1200);
    const haystack = (title + ' ' + snippet).toLowerCase();
    const urlLower = url.toLowerCase();
    let score = 0;
    if (trusted.some((domain) => urlLower.includes(domain))) score += 2;
    if (cities.some((place) => haystack.includes(place))) score += 2;
    if (eventWords.some((word) => haystack.includes(word))) score += 1;
    if (/20(26|27)/.test(haystack)) score += 1;
    candidates.push({ json: { title, url, snippet, score } });
  }
}

candidates.sort((a, b) => b.json.score - a.json.score);
return candidates;

const pages = $input.all();
const candidates = $('Extract candidate links').all();
const out = [];

for (let i = 0; i < pages.length; i++) {
  const candidate = candidates[i] ? candidates[i].json : {};
  const html = String(pages[i].json.data || '');
  if (html.length < 500) continue;
  const text = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
  if (text.length < 200) continue;
  out.push({ json: { url: candidate.url || '', title: candidate.title || '', pageText: text.slice(0, 12000) } });
}

return out;

const crypto = require('crypto');
const items = $input.all();
const sources = $('Read page text').all();
const cities = ['kochi', 'cochin', 'ernakulam', 'kalamassery', 'thrissur', 'kottayam', 'kozhikode', 'calicut'];
const out = [];
const todayIso = $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd');
const todayStart = new Date(todayIso + 'T00:00:00+05:30');
const sha = (value) => crypto.createHash('sha256').update(value).digest('hex');
const pick = (obj, key) => {
  if (!obj || obj[key] === undefined || obj[key] === null) return '';
  return String(obj[key]).trim();
};
const asBool = (value) => value === true || String(value).toLowerCase() === 'true';

for (let i = 0; i < items.length; i++) {
  const source = sources[i] ? sources[i].json : {};
  let payload = items[i].json || {};
  if (payload.output !== undefined) payload = payload.output;
  if (payload.text !== undefined) payload = payload.text;
  if (typeof payload === 'string') {
    try {
      payload = JSON.parse(payload);
    } catch (error) {
      continue;
    }
  }
  if (!payload || typeof payload !== 'object') continue;

  const name = pick(payload, 'name');
  if (!name) continue;
  if (!asBool(payload.is_technical)) continue;

  const city = pick(payload, 'city');
  const venue = pick(payload, 'venue');
  const where = (city + ' ' + venue + ' ' + pick(payload, 'description')).toLowerCase();
  if (!cities.some((place) => where.includes(place))) continue;

  const statusText = (pick(payload, 'registration_status') || 'not stated').toLowerCase();
  if (statusText.includes('closed') || statusText.includes('sold out') || statusText.includes('ended') || statusText.includes('full')) continue;
  const openish = statusText.includes('open') || statusText.includes('pending') || statusText.includes('not stated') || statusText.includes('register') || statusText.includes('coming');
  if (!openish) continue;

  const startDate = pick(payload, 'start_date');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate)) continue;
  const startAt = new Date(startDate + 'T00:00:00+05:30');
  if (isNaN(startAt.getTime())) continue;
  if (startAt.getTime() < todayStart.getTime()) continue;

  const event = {
    name,
    organizer: pick(payload, 'organizer'),
    event_type: pick(payload, 'event_type'),
    start_date: startDate,
    start_time: pick(payload, 'start_time'),
    city,
    venue,
    registration_status: pick(payload, 'registration_status'),
    registration_deadline: pick(payload, 'registration_deadline'),
    fee: pick(payload, 'fee'),
    eligibility: pick(payload, 'eligibility'),
    team_size: pick(payload, 'team_size'),
    registration_url: pick(payload, 'registration_url'),
    official_url: pick(payload, 'official_url') || source.url || '',
    description: pick(payload, 'description'),
    practical_relevance: pick(payload, 'practical_relevance'),
    is_technical: true,
    is_hands_on: asBool(payload.is_hands_on),
    source_url: source.url || ''
  };

  const normalize = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const statusBucket = (value) => {
    const text = String(value || '').toLowerCase();
    if (!text.trim()) return 'unknown';
    if (text.includes('closed') || text.includes('sold out') || text.includes('ended') || text.includes('full')) return 'closed';
    if (text.includes('open') || text.includes('register') || text.includes('available') || text.includes('apply')) return 'open';
    return 'other';
  };
  const keySource = [normalize(event.name), normalize(event.organizer), event.start_date].join('|');
  const eventKey = sha(keySource);
  const materialHash = sha(JSON.stringify({
    start_date: event.start_date,
    start_time: normalize(event.start_time),
    registration_status: statusBucket(event.registration_status),
    registration_deadline: normalize(event.registration_deadline),
    registration_url: normalize(event.registration_url),
    fee: normalize(event.fee)
  }));

  out.push({
    json: {
      event_key: eventKey,
      material_hash: materialHash,
      name: event.name,
      organizer: event.organizer,
      event_date: event.start_date,
      venue: event.venue,
      registration_status: event.registration_status,
      registration_url: event.registration_url,
      official_url: event.official_url,
      event_data: JSON.stringify(event)
    }
  });
}

return out;

const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => row && row.event_key);

const changed = rows.filter((row) => {
  const flag = row.material_changed;
  return !(flag === false || flag === 'false' || flag === 'f' || flag === 'F' || flag === 0 || flag === '0');
});

return changed.map((row) => ({ json: row }));

const LF = String.fromCharCode(10);
const rows = $input.all().map((item) => item.json);

const escapeHtml = (value) => String(value === undefined || value === null ? '' : value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const parseData = (value) => {
  if (!value) return {};
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (error) {
      return {};
    }
  }
  return value;
};

const blocks = [];
for (const row of rows) {
  const event = parseData(row.event_data);
  const isNew = !row.first_seen_at || String(row.first_seen_at) === String(row.last_changed_at);
  const lines = [(isNew ? '🆕 ' : '🔄 ') + '<b>' + escapeHtml(row.name) + '</b>'];
  const dateText = String(event.start_date || '').trim() || String(row.event_date || '').slice(0, 10);
  const when = [escapeHtml(dateText), escapeHtml(event.start_time)].filter((part) => part).join(' ');
  if (when) lines.push('📅 ' + when);
  const where = [escapeHtml(event.venue), escapeHtml(event.city)].filter((part) => part).join(', ');
  if (where) lines.push('📍 ' + where);
  if (event.registration_status) lines.push('🎟 Registration: ' + escapeHtml(event.registration_status));
  if (event.registration_deadline) lines.push('⏳ Deadline: ' + escapeHtml(event.registration_deadline));
  if (event.fee) lines.push('💰 Fee: ' + escapeHtml(event.fee));
  if (event.eligibility) lines.push('👤 Eligibility: ' + escapeHtml(event.eligibility));
  if (event.team_size) lines.push('👥 Team size: ' + escapeHtml(event.team_size));
  if (event.practical_relevance) lines.push('', escapeHtml(event.practical_relevance));
  const link = event.registration_url || row.registration_url || row.official_url;
  if (link) lines.push('🔗 Register: ' + escapeHtml(link));
  if (row.official_url && row.official_url !== link) lines.push('📄 Source: ' + escapeHtml(row.official_url));
  blocks.push(lines.join(LF));
}

const header = '<b>Kochi tech events - ' + $now.setZone('Asia/Kolkata').toFormat('dd LLL yyyy') + '</b>';
const messages = [];
let current = header;
for (const block of blocks) {
  const next = current + LF + LF + block;
  if (next.length > 3800 && current !== header) {
    messages.push(current);
    current = header + LF + LF + block;
  } else {
    current = next;
  }
}
if (current !== header) messages.push(current);

return messages.map((text) => ({ json: { text } }));
